{
  "implementation": "def solve(case):
    # Validate required fields
    required = ['initial_state', 'max_steps', 'tool_observations', 'transitions']
    for key in required:
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    # Validate transitions structure and state references
    all_states = set(transitions.keys())
    if initial not in all_states:
        raise ValueError(f"Initial state {initial!r} not in transitions")

    for state, trans in transitions.items():
        if not isinstance(trans, dict):
            raise ValueError(f"Transition for state {state!r} is not a dict")
        kind = trans.get('kind')
        if kind not in ('action', 'final'):
            raise ValueError(f"Unknown transition kind {kind!r} for state {state!r}")
        if kind == 'final':
            if 'value' not in trans:
                raise ValueError(f"Final state {state!r} missing 'value'")
        elif kind == 'action':
            for subkey in ('action', 'next_by_observation', 'default_next'):
                if subkey not in trans:
                    raise ValueError(f"Action state {state!r} missing {subkey!r}")
            nbo = trans['next_by_observation']
            if not isinstance(nbo, dict):
                raise ValueError(f"'next_by_observation' for state {state!r} is not a dict")
            # Validate referenced states
            for obs, ns in nbo.items():
                if ns not in all_states:
                    raise ValueError(f"State {ns!r} referenced from {state!r} not in transitions")
            default = trans['default_next']
            if default not in all_states:
                raise ValueError(f"Default next state {default!r} from {state!r} not in transitions")

    # Simulation
    current = initial
    step = 0
    trace = []

    while True:
        t = transitions[current]
        if t['kind'] == 'final':
            return {
                'final': t['value'],
                'status': 'completed',
                'trace': trace
            }
        elif t['kind'] == 'action':
            if step >= max_steps:
                return {
                    'final': None,
                    'status': 'incomplete',
                    'trace': trace
                }
            action = t['action']
            # Obtain observation
            if action in tool_obs:
                observation = tool_obs[action]
            else:
                observation = 'invalid'
            # Determine next state
            nbo = t['next_by_observation']
            if observation in nbo:
                next_state = nbo[observation]
            else:
                next_state = t['default_next']
            step += 1
            trace.append({
                'step': step,
                'action': action,
                'observation': observation,
                'state': next_state
            })
            current = next_state
        else:
            raise ValueError(f"Unexpected transition kind for state {current!r}")"
}
